import numpy as np


def f(x, d=2): return f"{x:.{d}f}"
def pc(x, d=1): return f"{100*x:.{d}f}"
def ci(lo, hi, d=2): return f"[{lo:.{d}f}, {hi:.{d}f}]"
def excl0(lo, hi): return (lo > 0) or (hi < 0)
def p3(p): return "< 0.001" if p < 0.001 else f"= {p:.3f}"


